contracts/GainixBotPass.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {GainixErrors} from "./libraries/GainixErrors.sol";

/// @title GainixBotPass
/// @notice Utility subscription contract for bot execution cycles/trades. No profit guarantees.
contract GainixBotPass is Ownable2Step, ReentrancyGuard, Pausable {
    struct Plan {
        uint256 priceWei;
        uint256 cycles;
        bool active;
    }

    struct Subscription {
        uint256 planId;
        uint256 remainingCycles;
        uint64 startedAt;
        uint64 expiresAt;
        uint256 totalPurchases;
    }

    address public treasury;
    uint64 public subscriptionPeriod = 30 days;

    mapping(uint256 => Plan) public plans;
    mapping(address => Subscription) private _subscriptions;
    mapping(address => bool) public operators;

    event PlanConfigured(uint256 indexed planId, uint256 priceWei, uint256 cycles, bool active);
    event TreasuryUpdated(address indexed previousTreasury, address indexed newTreasury);
    event OperatorUpdated(address indexed operator, bool isOperator);
    event BotPassPurchased(
        address indexed user,
        uint256 indexed planId,
        uint256 amountPaid,
        uint256 cyclesAdded,
        bool renewal,
        uint256 timestamp
    );
    event SubscriptionUpdated(address indexed user, uint256 planId, uint256 remainingCycles);
    event CycleConsumed(address indexed user, uint256 amount, uint256 remainingCycles);
    event SubscriptionPeriodUpdated(uint64 oldPeriod, uint64 newPeriod);

    modifier onlyOperatorOrOwner() {
        if (msg.sender != owner() && !operators[msg.sender]) {
            revert GainixErrors.Unauthorized();
        }
        _;
    }

    constructor(
        address initialOwner,
        address initialTreasury,
        uint256[] memory planIds,
        uint256[] memory pricesWei,
        uint256[] memory cycles
    ) Ownable(initialOwner) {
        if (initialOwner == address(0) || initialTreasury == address(0)) {
            revert GainixErrors.ZeroAddress();
        }
        if (planIds.length != pricesWei.length || planIds.length != cycles.length) {
            revert GainixErrors.ArrayLengthMismatch();
        }

        treasury = initialTreasury;

        for (uint256 i = 0; i < planIds.length; i++) {
            _setPlan(planIds[i], pricesWei[i], cycles[i], true);
        }
    }

    /// @notice Subscribe or switch plans by paying the selected plan price.
    function subscribe(uint256 planId) external payable nonReentrant whenNotPaused {
        _purchase(planId, false);
    }

    /// @notice Renew current or selected plan by paying the plan price.
    function renewSubscription(uint256 planId) external payable nonReentrant whenNotPaused {
        _purchase(planId, true);
    }

    /// @notice Returns compact subscription shape expected by frontend contract hooks.
    function subscriptionOf(address user) external view returns (uint256 planId, uint256 remainingCycles, bool active) {
        Subscription memory sub = _subscriptions[user];
        active = _isSubscriptionActive(sub);
        return (sub.planId, sub.remainingCycles, active);
    }

    function getSubscription(address user) external view returns (Subscription memory) {
        return _subscriptions[user];
    }

    function consumeCycles(address user, uint256 amount) external onlyOperatorOrOwner whenNotPaused {
        if (user == address(0)) revert GainixErrors.ZeroAddress();
        if (amount == 0) revert GainixErrors.InvalidAmount();

        Subscription storage sub = _subscriptions[user];
        if (!_isSubscriptionActive(sub)) revert GainixErrors.Unauthorized();
        if (sub.remainingCycles < amount) revert GainixErrors.InvalidAmount();

        sub.remainingCycles -= amount;
        emit CycleConsumed(user, amount, sub.remainingCycles);
        emit SubscriptionUpdated(user, sub.planId, sub.remainingCycles);
    }

    function configurePlan(uint256 planId, uint256 priceWei, uint256 cycles, bool active) external onlyOwner {
        _setPlan(planId, priceWei, cycles, active);
    }

    function setTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert GainixErrors.ZeroAddress();
        address previous = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(previous, newTreasury);
    }

    function setOperator(address operator, bool isOperator) external onlyOwner {
        if (operator == address(0)) revert GainixErrors.ZeroAddress();
        operators[operator] = isOperator;
        emit OperatorUpdated(operator, isOperator);
    }

    function setSubscriptionPeriod(uint64 newPeriod) external onlyOwner {
        if (newPeriod == 0) revert GainixErrors.InvalidAmount();
        uint64 old = subscriptionPeriod;
        subscriptionPeriod = newPeriod;
        emit SubscriptionPeriodUpdated(old, newPeriod);
    }

    function withdraw() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        if (balance == 0) return;

        (bool sent, ) = payable(treasury).call{value: balance}("");
        if (!sent) revert GainixErrors.InvalidAmount();
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function _purchase(uint256 planId, bool renewal) internal {
        Plan memory plan = plans[planId];
        if (!plan.active) revert GainixErrors.PlanNotActive();
        if (msg.value < plan.priceWei) {
            revert GainixErrors.InsufficientPayment(plan.priceWei, msg.value);
        }

        Subscription storage sub = _subscriptions[msg.sender];

        uint256 newCycles = _isSubscriptionActive(sub) ? sub.remainingCycles + plan.cycles : plan.cycles;

        sub.planId = planId;
        sub.remainingCycles = newCycles;
        sub.startedAt = uint64(block.timestamp);
        sub.expiresAt = uint64(block.timestamp + subscriptionPeriod);
        sub.totalPurchases += 1;

        emit BotPassPurchased(msg.sender, planId, plan.priceWei, plan.cycles, renewal, block.timestamp);
        emit SubscriptionUpdated(msg.sender, sub.planId, sub.remainingCycles);

        uint256 refund = msg.value - plan.priceWei;
        if (refund > 0) {
            (bool refunded, ) = payable(msg.sender).call{value: refund}("");
            if (!refunded) revert GainixErrors.InvalidAmount();
        }
    }

    function _setPlan(uint256 planId, uint256 priceWei, uint256 cycles, bool active) internal {
        if (priceWei == 0 || cycles == 0) revert GainixErrors.InvalidAmount();
        plans[planId] = Plan({priceWei: priceWei, cycles: cycles, active: active});
        emit PlanConfigured(planId, priceWei, cycles, active);
    }

    function _isSubscriptionActive(Subscription memory sub) internal view returns (bool) {
        if (sub.planId == 0 || sub.remainingCycles == 0) return false;
        return sub.expiresAt >= block.timestamp;
    }
}

contracts/GainixMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {IGainixNFT} from "./interfaces/IGainixNFT.sol";
import {GainixErrors} from "./libraries/GainixErrors.sol";

/// @title GainixMarketplace
/// @notice Escrow marketplace for ERC-721 listings on BNB Smart Chain.
contract GainixMarketplace is Ownable2Step, ReentrancyGuard, Pausable, IERC721Receiver {
    struct Listing {
        uint256 listingId;
        address nftContract;
        uint256 tokenId;
        address seller;
        uint256 price;
        bool isActive;
        uint64 createdAt;
        uint64 updatedAt;
    }

    uint96 public constant MAX_FEE_BPS = 1_000; // 10%

    uint256 public nextListingId = 1;
    uint96 public marketplaceFeeBps;
    address public feeRecipient;

    mapping(uint256 => Listing) public listings;
    mapping(address => mapping(uint256 => uint256)) public activeListingIdByToken;

    event ListingCreated(
        uint256 indexed listingId,
        address indexed seller,
        uint256 price,
        address indexed nftContract,
        uint256 tokenId,
        uint256 timestamp
    );
    event ListingCancelled(uint256 indexed listingId, address indexed seller, uint256 timestamp);
    event ListingFilled(
        uint256 indexed listingId,
        address indexed buyer,
        uint256 price,
        address indexed seller,
        uint256 feePaid,
        uint256 timestamp
    );
    event MarketplaceFeeUpdated(uint96 oldFeeBps, uint96 newFeeBps);
    event FeeRecipientUpdated(address indexed oldRecipient, address indexed newRecipient);

    constructor(address initialOwner, address initialFeeRecipient, uint96 initialFeeBps) Ownable(initialOwner) {
        if (initialOwner == address(0) || initialFeeRecipient == address(0)) {
            revert GainixErrors.ZeroAddress();
        }
        if (initialFeeBps > MAX_FEE_BPS) revert GainixErrors.InvalidAmount();

        feeRecipient = initialFeeRecipient;
        marketplaceFeeBps = initialFeeBps;
    }

    /// @notice Create an active listing and transfer NFT into escrow.
    function listItem(address nftContract, uint256 tokenId, uint256 price) external whenNotPaused {
        if (nftContract == address(0)) revert GainixErrors.ZeroAddress();
        if (price == 0) revert GainixErrors.InvalidPrice();

        uint256 activeId = activeListingIdByToken[nftContract][tokenId];
        if (activeId != 0 && listings[activeId].isActive) revert GainixErrors.AlreadyListed();

        IGainixNFT nft = IGainixNFT(nftContract);
        if (nft.ownerOf(tokenId) != msg.sender) revert GainixErrors.Unauthorized();

        uint256 listingId = nextListingId;
        unchecked {
            nextListingId = listingId + 1;
        }

        listings[listingId] = Listing({
            listingId: listingId,
            nftContract: nftContract,
            tokenId: tokenId,
            seller: msg.sender,
            price: price,
            isActive: true,
            createdAt: uint64(block.timestamp),
            updatedAt: uint64(block.timestamp)
        });

        activeListingIdByToken[nftContract][tokenId] = listingId;

        nft.safeTransferFrom(msg.sender, address(this), tokenId);

        emit ListingCreated(listingId, msg.sender, price, nftContract, tokenId, block.timestamp);
    }

    /// @notice Cancel active listing and return NFT to seller.
    function cancelListing(uint256 listingId) external nonReentrant whenNotPaused {
        Listing storage listing = listings[listingId];
        if (listing.listingId == 0) revert GainixErrors.ListingNotFound();
        if (!listing.isActive) revert GainixErrors.ListingNotActive();

        bool canCancel = msg.sender == listing.seller || msg.sender == owner();
        if (!canCancel) revert GainixErrors.Unauthorized();

        listing.isActive = false;
        listing.updatedAt = uint64(block.timestamp);
        activeListingIdByToken[listing.nftContract][listing.tokenId] = 0;

        IGainixNFT(listing.nftContract).safeTransferFrom(address(this), listing.seller, listing.tokenId);

        emit ListingCancelled(listingId, listing.seller, block.timestamp);
    }

    /// @notice Buy an active listing by paying exact or greater amount; any overpayment is refunded.
    function buyItem(uint256 listingId) external payable nonReentrant whenNotPaused {
        Listing storage listing = listings[listingId];
        if (listing.listingId == 0) revert GainixErrors.ListingNotFound();
        if (!listing.isActive) revert GainixErrors.ListingNotActive();

        uint256 price = listing.price;
        if (msg.value < price) revert GainixErrors.InsufficientPayment(price, msg.value);

        listing.isActive = false;
        listing.updatedAt = uint64(block.timestamp);
        activeListingIdByToken[listing.nftContract][listing.tokenId] = 0;

        uint256 fee = (price * marketplaceFeeBps) / 10_000;
        uint256 sellerPayout = price - fee;

        IGainixNFT(listing.nftContract).safeTransferFrom(address(this), msg.sender, listing.tokenId);

        (bool sellerSent, ) = payable(listing.seller).call{value: sellerPayout}("");
        if (!sellerSent) revert GainixErrors.InvalidAmount();

        if (fee > 0) {
            (bool feeSent, ) = payable(feeRecipient).call{value: fee}("");
            if (!feeSent) revert GainixErrors.InvalidAmount();
        }

        uint256 refund = msg.value - price;
        if (refund > 0) {
            (bool refunded, ) = payable(msg.sender).call{value: refund}("");
            if (!refunded) revert GainixErrors.InvalidAmount();
        }

        emit ListingFilled(listingId, msg.sender, price, listing.seller, fee, block.timestamp);
    }

    function updateMarketplaceFee(uint96 newFeeBps) external onlyOwner {
        if (newFeeBps > MAX_FEE_BPS) revert GainixErrors.InvalidAmount();
        uint96 old = marketplaceFeeBps;
        marketplaceFeeBps = newFeeBps;
        emit MarketplaceFeeUpdated(old, newFeeBps);
    }

    function updateFeeRecipient(address newFeeRecipient) external onlyOwner {
        if (newFeeRecipient == address(0)) revert GainixErrors.ZeroAddress();
        address old = feeRecipient;
        feeRecipient = newFeeRecipient;
        emit FeeRecipientUpdated(old, newFeeRecipient);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function getListing(uint256 listingId) external view returns (Listing memory) {
        return listings[listingId];
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

contracts/GainixNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";

import {GainixErrors} from "./libraries/GainixErrors.sol";

/// @title GainixNFT
/// @notice ERC-721 collection contract with owner/admin mint support and token URI management.
contract GainixNFT is ERC721URIStorage, Ownable2Step {
    uint256 private _nextTokenId;
    string private _baseTokenUri;

    mapping(address => bool) public admins;

    event AdminUpdated(address indexed account, bool isAdmin);
    event AdminMint(address indexed operator, address indexed to, uint256 indexed tokenId, string tokenUri);
    event BaseTokenUriUpdated(string previousBaseUri, string newBaseUri);
    event TokenUriUpdated(uint256 indexed tokenId, string tokenUri);

    modifier onlyAdminOrOwner() {
        if (msg.sender != owner() && !admins[msg.sender]) {
            revert GainixErrors.Unauthorized();
        }
        _;
    }

    /// @param name_ ERC-721 name.
    /// @param symbol_ ERC-721 symbol.
    /// @param initialOwner Contract owner/admin manager.
    /// @param initialBaseTokenUri Optional base URI prefix.
    /// @param startTokenId Starting token id for incremental mints.
    constructor(
        string memory name_,
        string memory symbol_,
        address initialOwner,
        string memory initialBaseTokenUri,
        uint256 startTokenId
    ) ERC721(name_, symbol_) Ownable(initialOwner) {
        if (initialOwner == address(0)) revert GainixErrors.ZeroAddress();
        admins[initialOwner] = true;
        _baseTokenUri = initialBaseTokenUri;
        _nextTokenId = startTokenId;

        emit AdminUpdated(initialOwner, true);
    }

    /// @notice Adds or removes an admin wallet that can mint and update token URIs.
    function setAdmin(address account, bool isAdmin) external onlyOwner {
        if (account == address(0)) revert GainixErrors.ZeroAddress();
        admins[account] = isAdmin;
        emit AdminUpdated(account, isAdmin);
    }

    /// @notice Owner can update base URI used as prefix by metadata clients.
    function setBaseTokenUri(string calldata newBaseTokenUri) external onlyOwner {
        string memory previous = _baseTokenUri;
        _baseTokenUri = newBaseTokenUri;
        emit BaseTokenUriUpdated(previous, newBaseTokenUri);
    }

    /// @notice Mints an NFT to `to` and sets token URI.
    /// @dev Admin/owner mint flow used by curation or allowlisted mint backoffice.
    function adminMint(address to, string calldata uri) external onlyAdminOrOwner returns (uint256 tokenId) {
        if (to == address(0)) revert GainixErrors.ZeroAddress();

        tokenId = _nextTokenId;
        unchecked {
            _nextTokenId = tokenId + 1;
        }

        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);

        emit AdminMint(msg.sender, to, tokenId, uri);
    }

    /// @notice Updates token-level URI for an existing NFT.
    function setTokenUri(uint256 tokenId, string calldata uri) external onlyAdminOrOwner {
        _requireOwned(tokenId);
        _setTokenURI(tokenId, uri);
        emit TokenUriUpdated(tokenId, uri);
    }

    /// @notice Burns a token. Caller must be owner or approved wallet for that token.
    function burn(uint256 tokenId) public {
        address tokenOwner = ownerOf(tokenId);
        if (!_isAuthorized(tokenOwner, msg.sender, tokenId)) {
            revert GainixErrors.Unauthorized();
        }
        _burn(tokenId);
    }

    function nextTokenId() external view returns (uint256) {
        return _nextTokenId;
    }

    function _baseURI() internal view override returns (string memory) {
        return _baseTokenUri;
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

